import json,sqlite3
with open('json/circuits.json') as f:
    circuits={c['circuitId']:c['country'] for c in json.load(f)['records']}
con=sqlite3.connect('db/races.db')
cur=con.cursor()
cur.execute('SELECT raceId,name,circuitId FROM races')
races=cur.fetchall()
con.close()
EURO={'Austria','Belgium','France','Germany','Great Britain','Hungary','Italy','Monaco','Netherlands','Portugal','Spain','Switzerland','Turkey','UK','San Marino','Luxembourg','Russia','Poland','Czech Republic','Belarus','Serbia'}
euro_gp=0
ger_gp=0
for rid,name,cid in races:
    if 'Grand Prix' in name:
        ct=circuits.get(cid)
        if ct and ct in EURO:
            euro_gp+=1
            if ct=='Germany':ger_gp+=1
print(f"European GP: {euro_gp}")
print(f"German GP: {ger_gp}")
if euro_gp>0: print(f"Percentage: {(ger_gp/euro_gp)*100:.2f}%")

